<?php require 'config.php'; $children=$pdo->query("SELECT id,name FROM children ORDER BY name")->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$child=(int)($_POST['child_id']??0);$date=$_POST['date']??date('Y-m-d');$status=$_POST['status']??'Present';if($child){$pdo->prepare("INSERT INTO attendance(child_id,date,status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status)")->execute([$child,$date,$status]);header('Location:index.php#attendance');exit;} $error='Please select a child.';} ?><!DOCTYPE html><html><head><meta charset="UTF-8"><link rel="stylesheet" href="assets/style.css"><title>Attendance | CareTrack</title></head><body><main class="form-page"><a href="index.php">← Dashboard</a><section class="panel"><h1>Mark attendance</h1><?php if($error) echo '<p class="error">'.$error.'</p>'; ?><form method="post"><label>Child<select name="child_id" required><option value="">Select child</option><?php foreach($children as $c): ?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach; ?></select></label><label>Date<input type="date" name="date" value="<?=date('Y-m-d')?>" required></label><label>Status<select name="status"><option>Present</option><option>Absent</option><option>Late</option></select></label><button class="button">Save attendance</button></form></section></main></body></html>